-- Rifts World Book 27: Adventures in Dinosaur Swamp - its bestiary and its notable NPCs.
-- 0 creatures (migration 074) and 2 notable NPCs (migration 072),
-- with their attacks in stat_attacks (migration 073).
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~258-adventures-in-dinosaur-swamp-char.sql
--
-- Written by scripts/bestiary-sql.mjs from 1 worker file(s). Every
-- creature row passes creatureFormulaGaps, every value is printable ASCII,
-- and an 8-word shingle check of the prose fields against the book's cached text finds no copied run.

INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES
('jonny-maraschoc', 'Jonny Maraschoc', 'Jonathan Livingstone Maraschoc', 'Legacy Scout and relic hunter', 'rifts', NULL, '8th level Legacy Scout and explorer', 8, 'Unprincipled', '37 (looks 20 or 21)', '5 feet, 6 inches (1.7 m)', '128 lbs (57.6 kg)', '{"IQ":14,"ME":9,"MA":13,"PS":17,"PP":13,"PE":18,"PB":12,"Spd":14}', 40, 35, NULL, 8, NULL, NULL, NULL, '{"attacks":5,"strike":1,"parry":3,"dodge":3,"damage":2,"roll":3,"pull":2}', 'Hand to Hand: Basic. +5 to save vs poison, +3 vs disease, +2 vs magic, +3 vs Horror Factor. M.D.C. by armor only, typically medium. Male. Occupation: explorer and scavenger of artifacts and oddities.', '[{"name":"Archaeology","pct":70},{"name":"Bicycling","pct":82},{"name":"Climbing","pct":80},{"name":"Gemology","pct":80},{"name":"History (North America Post-Apocalypse)","pct":85},{"name":"Land Navigation","pct":84},{"name":"Literacy","pct":40},{"name":"Lore: Magic","pct":85},{"name":"Salvage","pct":80},{"name":"Wilderness Survival","pct":85}]', 'Athletics (General), History (Pre-Rifts) 74%/64%, W.P. Energy Pistol, W.P. Energy Rifle.', NULL, 'Lore only.', 'None. I.S.P. none.', NULL, NULL, 'Pre-Rifts NEMA gear from a cache only he knows (Rifts Chaos Earth has its stats): a black and gray armored trench coat (32 M.D.C.) over an armored vest (30 M.D.C.), sometimes an environmental helmet; a heavy ion pistol shaped like an old Coalition laser pistol; a Vibro-Dagger (1D6 M.D.); a SteelTree staff (2D4 M.D. as printed here); a revolver with silver bullets; a Triax particle beam rifle (6D6+6 M.D.); a Spider Probe Reconnaissance Robot with its handheld monitor. Basic kit: internal frame backpack and web belt, two canteens, compass, hand axe (1D6 S.D.C.), gas mask, air filter, tinted goggles, sunglasses, two flashlights, sacks.', '2.9 million credits in banks in the north and west; 11,000 kept in Char.', 'Shy and quiet with strangers, chatty with friends, and wildly excited by any relic, firing questions like a child. Freezes and stammers before authority, talks to his gear as if it were a partner, and is gentle and steady in a crisis.', NULL, NULL, 'A slight, freckled, sandy-haired explorer from an Arkansas farm family who has spent 21 years in Dinosaur Swamp digging up pre-Rifts ruins and sells his finds to dealers in Lazlo, New Lazlo and the Chi-Town ''Burbs. Most of Char takes him for a harmless eccentric; few know he is rich, and his reading is poor though his memory is excellent.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.95-97'),
('silas-skinwalker', 'Silas Skinwalker', NULL, 'Self-proclaimed King of the Dead', 'rifts', 'Unknown; perhaps a demon species from the time of the Great Cataclysm', 'Equal to a 10th level (otherworldly) Necromancer', 10, 'Diabolic', 'Unknown; rumored to have claimed Hickory more than 200 years ago', '8 feet, 2 inches (2.49 m)', '452 lbs (203.4 kg)', '{"IQ":17,"ME":14,"MA":21,"PS":21,"PP":17,"PE":16,"PB":19,"Spd":22}', NULL, NULL, 188, 136, NULL, NULL, 12, '{"attacks":8,"initiative":2,"strike":4,"parry":4,"dodge":6,"damage":8,"roll":4,"pull":4}', '+3 on Perception Rolls. The damage bonus is to S.D.C. damage. +2 to save vs magic, +6 vs Horror Factor, +4 vs possession, impervious to mind control; 45% charm/impress, 65% trust/intimidate. Every bonus is halved (round down) in daytime. P.S. is Supernatural; Spd doubles at night. Horror Factor 15 if he is recognized as a Necromancer. Weapons of light, lasers included, do him 50% more damage; he cannot swim. Male. Real name unknown.', '[{"name":"Land Navigation","pct":80},{"name":"Lore: Monster & Demon","pct":90},{"name":"Lore: Magic","pct":80},{"name":"Interrogation (Torture)","pct":85},{"name":"Prowl","pct":70},{"name":"Skin and Prepare Animal Hides","pct":80},{"name":"Wilderness Survival","pct":85}]', 'Climbing 90%/80%.', 'Nightvision 400 feet (122 m); leaps 20 feet (6 m) up or across; recognize common smells 77%; Track by Smell 56%; scents death and decay at 88% from 12 miles (19.2 km) away, and from three times as far once more than a dozen lie dead or dying; bio-regenerates 2D6 M.D. per melee round. Senses death within 100 miles (160 km) of his domain, and anything larger than a cat that lies dead in his kingdom over 48 hours rises with the next moon as his servant.', 'All Necromancy powers and spells, and Bone Magic. Necromantic abilities: Union with the Dead, Augmentation/Additional Appendages, Animate and Control the Dead (three times the usual number), Impervious to Vampires.', 'None as such; can raise a Mind Block at will, lasting 10 minutes. I.S.P. none.', NULL, NULL, 'Carries no weapons or armor. His Necromantic arsenal includes a set of Allosaurus claws (Necromancy: Dinosaur Forearm Claws (T-Rex/Large Predator)), Tiger Raptor clawed feet (Necromancy: Dinosaur Limbs/Feet (Predator)), two pairs of Terrordactyl wings (Necromancy: Dinosaur/Pterosaur Wings), a Tyrannosaurus Rex skull (Necromancy: Dinosaur Skull (T-Rex/Large Predator)), an Eye of Eylor and the tongue of a Splugorth Conservator; their uses are in Rifts World Book 26: Dinosaur Swamp p.99-101. Companions: summons 2D6+2 skeletal minions anywhere in his territory within one melee round, commands three times a 10th level Necromancer''s skeletons plus three zombies and two mummies, and keeps three or four dinosaur or animal skeletons with him, sometimes a skeletal Tyrannosaur.', 'Pays 200 credits (or trade) per corpse brought to him.', 'Usually cool and calculating but plainly not of this world, polite one moment and savage the next; insane, evil and certain that every living thing will one day be his. Obsessions: hates daylight, loves torturing victims, demands to be treated as a king. Never spends more than one night away from his domain, and fights, bargains or seduces his way back if kept from it.', NULL, NULL, 'An eight-foot, gray-furred, wolf-faced being with milky-pink eyes who rules the ruins of Hickory, north-northwest of Char, as his Kingdom of the Dead, and was already there before the first Neenok expedition in 82 P.A. Travelers who bow to him may pass or be sent on errands; those who offend him join his dead. Even other Necromancers avoid him.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.97-99');

