-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 2 notable NPCs are in' AS assertion, count(*) AS got, 2 AS want
  FROM notable_npcs WHERE slug IN ('jonny-maraschoc', 'silas-skinwalker');
SELECT 'and the notables 6' AS assertion, count(*) AS got, 6 AS want
  FROM stat_attacks WHERE owner_kind = 'notable_npc' AND owner_slug IN ('jonny-maraschoc', 'silas-skinwalker');

